    webSearch: {"type": "function", "function": {"name": "webSearch", "description": "Search the web using Bing, Exa, Parallel, TinyFish or Fusion. Returns compact relevant results with citations, provider errors and resumable refs. Read more using ref/offset/maxChars or resultOffset. Open relevant URLs with webFetch to verify; unrelated results are not evidence.", "parameters": {"type": "object", "properties": {"ref": {"type": "string", "description": "Reuse returned snapshot ref to read more without repeating network requests (30-minute retention)."}, "offset": {"type": "integer", "description": "Character offset into the retained full content; default 0."}, "maxChars": {"type": "integer", "description": "Content characters per response; default 6000, 0 reads all. nextOffset is returned."}, "query": {"type": "string", "description": "Search terms; required for a new search, omitted with ref."}, "engine": {"type": "string", "enum": ["bing", "exa", "parallel", "tinyfish", "fusion"], "description": "Override configured engine. fusion searches all four, deduplicates and ranks by query relevance and source agreement."}, "numResults": {"type": "integer", "description": "Results per page, default 8, maximum 100."}, "resultOffset": {"type": "integer", "description": "Result page offset, default 0. Use nextResultOffset to continue."}, "snippetChars": {"type": "integer", "description": "Characters per snippet, default 500; 0 returns full snippets."}, "includeContent": {"type": "boolean", "description": "Also read retained complete source text, with offset/maxChars."}, "providerMaxChars": {"type": "integer", "description": "Exa requested content budget; default 50000. Increase for deeper research."}, "type": {"type": "string", "enum": ["auto", "fast", "deep"]}}}}},
    webFetch: {"type": "function", "function": {"name": "webFetch", "description": "Read web content in compact resumable pages. Returns totalChars, nextOffset, ref and truncation metadata. Use the same ref with nextOffset to read every remaining character; maxChars=0 explicitly reads all. Prefer markdown/text; request html only when source markup is needed.", "parameters": {"type": "object", "properties": {"ref": {"type": "string", "description": "Reuse returned snapshot ref to read more without repeating network requests (30-minute retention)."}, "offset": {"type": "integer", "description": "Character offset into the retained full content; default 0."}, "maxChars": {"type": "integer", "description": "Content characters per response; default 6000, 0 reads all. nextOffset is returned."}, "url": {"type": "string", "description": "HTTP(S) URL; required unless ref is supplied."}, "urls": {"type": "array", "items": {"type": "string"}, "description": "Batch URLs, optional instead of url. Paging parameters apply separately to each URL."}, "format": {"type": "string", "enum": ["markdown", "text", "html"], "description": "Default markdown: removes navigation/scripts. html retains the original source."}, "refresh": {"type": "boolean", "description": "Bypass five-minute URL cache."}, "timeoutMs": {"type": "integer", "description": "Network timeout, maximum 120000 ms."}, "maxBytes": {"type": "integer", "description": "Network response limit; default 20 MB, up to 100 MB. This does not truncate retained text."}}}}},
    offscreenRenderOCR: { type: 'function', function: { name: 'offscreenRenderOCR', description: '离屏打开指定URL（不调用外部浏览器），等待渲染后截屏并OCR提取页面文本。用于动态网页内容抓取前，必须先使用webSearch拿到准确URL。', parameters: { type: 'object', properties: { url: { type: 'string', description: '目标URL（建议来自webSearch结果）' }, waitMs: { type: 'number', description: '渲染等待毫秒数，默认10000' }, width: { type: 'number', description: '截图宽度，默认1366' }, height: { type: 'number', description: '截图高度，默认900' } }, required: ['url'] } } },
    offscreenRenderContent: { type: 'function', function: { name: 'offscreenRenderContent', description: '离屏打开指定URL并等待页面渲染后，直接提取页面已渲染内容（文本/HTML），不进行OCR。可选保存截图。', parameters: { type: 'object', properties: { url: { type: 'string', description: '目标URL（建议来自webSearch结果）' }, waitMs: { type: 'number', description: '渲染等待毫秒数，默认10000' }, width: { type: 'number', description: '渲染宽度，默认1366' }, height: { type: 'number', description: '渲染高度，默认900' }, captureScreenshot: { type: 'boolean', description: '是否保存截图（默认true）' }, includeHtml: { type: 'boolean', description: '是否返回渲染后的HTML（默认true）' } }, required: ['url'] } } },
    knowledgeBaseSearch: { type: 'function', function: { name: 'knowledgeBaseSearch', description: '搜索知识库', parameters: { type: 'object', properties: { query: { type: 'string', description: '搜索关键词' } }, required: ['query'] } } },
    knowledgeBaseAdd: { type: 'function', function: { name: 'knowledgeBaseAdd', description: '向知识库添加信息', parameters: { type: 'object', properties: { items: { type: 'array', items: { type: 'object', properties: { title: { type: 'string' }, content: { type: 'string' } }, required: ['title', 'content'] }, description: '批量添加多条知识（与 title+content 单条二选一）' }, title: { type: 'string', description: '标题' }, content: { type: 'string', description: '内容' } }, required: ['title', 'content'] } } },
    knowledgeBaseDelete: { type: 'function', function: { name: 'knowledgeBaseDelete', description: '从知识库删除信息', parameters: { type: 'object', properties: { id: { type: 'string', description: '知识条目ID' } }, required: ['id'] } } },
    knowledgeBaseUpdate: { type: 'function', function: { name: 'knowledgeBaseUpdate', description: '更新知识库信息', parameters: { type: 'object', properties: { id: { type: 'string', description: '知识条目ID' }, title: { type: 'string' }, content: { type: 'string' } }, required: ['id'] } } },
    memorySearch: { type: 'function', function: { name: 'memorySearch', description: '搜索长期记忆', parameters: { type: 'object', properties: { query: { type: 'string', description: '搜索关键词' } }, required: ['query'] } } },
    memoryAdd: { type: 'function', function: { name: 'memoryAdd', description: '添加长期记忆', parameters: { type: 'object', properties: { items: { type: 'array', items: { type: 'object', properties: { content: { type: 'string' }, tags: { type: 'array', items: { type: 'string' } } }, required: ['content'] }, description: '批量添加多条长期记忆（与 content 单条二选一）' }, content: { type: 'string', description: '记忆内容' }, tags: { type: 'array', items: { type: 'string' }, description: '标签' } }, required: ['content'] } } },
